```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    string ans;
    ans.reserve(s.size() + s.size() / 4 + 1);

    for (size_t i = 0; i < s.size();) {
        // 当前位置开始正好是 "AGCT"：整段换成 "AG/CT"，往后跳 4 个字符
        if (i + 4 <= s.size() && s.compare(i, 4, "AGCT") == 0) {
            ans += "AG/CT";
            i += 4;
        } else {
            // 否则原样搬一个字符过去
            ans += s[i];
            i++;
        }
    }

    cout << ans << "\n";
    return 0;
}
```

### 易错点

尝试四字符匹配前确认剩余长度够；插入斜杠不会引出新的 DNA 匹配。

